rule('HAEMOLYSIS_CONFIRMED_REDUCED',all_(c('haemoglobin_g_dl','<',10),c('haemolytic_anaemia_status','==','confirmed')),'withhold_then_reduce','Confirmed haemolytic anaemia with haemoglobin <10 g/dL: withhold until resolution, then reduced-dose restart.','4',extra=review)
rule('HAEMOLYSIS_STATUS_REVIEW',c('haemolytic_anaemia_status','in',['suspected','confirmed']),'consultant_review','Investigate haemolysis and confirm haemoglobin/cause/recovery. The explicit dose row requires haemoglobin <10 g/dL; no automatic restart from status alone.','6 (4.4)',S,review)
rule('GI_PERFORATION_REVIEW',c('gi_perforation','==',True),'withhold','Urgently manage gastrointestinal perforation; consider discontinuation with the Consultant. SmPC says consider discontinuation, not an automatic permanent stop.','6 (4.4)',S,review)
